from collections import Counter

def transform_fixed(grid):
    # Identify background color (most frequent)
    all_values = []
    for row in grid:
        all_values.extend(row)
    bg_color = Counter(all_values).most_common(1)[0][0]

    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find all non-background regions
    visited = {}
    regions = {}

    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != bg_color:
                color = grid[r][c]
                if color not in regions:
                    regions[color] = []

    # BFS for each color
    for color in list(regions.keys()):
        for r in range(n_rows):
            for c in range(n_cols):
                if grid[r][c] == color and (r, c) not in visited:
                    cells = []
                    queue = [(r, c)]
                    visited[(r, c)] = True
                    cells.append((r, c))

                    while queue:
                        cr, cc = queue.pop(0)
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < n_rows and 0 <= nc < n_cols and grid[nr][nc] == color and (nr, nc) not in visited:
                                visited[(nr, nc)] = True
                                queue.append((nr, nc))
                                cells.append((nr, nc))
                    regions[color] = cells

    # For each region, fill interior
    for color, cells in regions.items():
        # Get bounding box
        rows = [c[0] for c in cells]
        cols = [c[1] for c in cells]
        r_min, r_max = min(rows), max(rows)
        c_min, c_max = min(cols), max(cols)

        r_start = r_min + 1
        r_end = r_max - 1
        c_start = c_min + 1
        c_end = c_max - 1

        # Determine fill color based on input color
        if color == 6 or color == 5:
            fill_color = 2
        elif color == 4 or color == 1:
            fill_color = 7
        else:
            fill_color = 2

        # Apply fill only to interior (not background cells)
        for r in range(n_rows):
            for c in range(n_cols):
                if r_start <= r <= r_end and c_start <= c <= c_end:
                    # Only fill if it's an empty cell inside the region
                    if grid[r][c] == bg_color:
                        grid[r][c] = fill_color

    return grid

